fn starts_with(s: &[char], p: &[char]) -> bool {
    // If prefix is empty, it always matches
    if p.is_empty() {
        return true;
    }
    
    // Sequence must be at least as long as prefix
    if s.len() < p.len() {
        return false;
    }
    
    // Check each character in the prefix
    for i in 0..p.len() {
        if s[i] != p[i] {
            return false;
        }
    }
    
    true
}

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // This is essentially the same as starts_with but takes Vec references
    starts_with(v, p)
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut result = Vec::new();
    
    for seq in xs {
        if has_prefix(&seq, &p) {
            result.push(seq);
        }
    }
    
    result
}